-- Additive compatibility layer: existing application continues to use offers.
CREATE TABLE IF NOT EXISTS rate_content (
 tenant_id TEXT NOT NULL,rate_id TEXT NOT NULL,eyebrow TEXT,long_description TEXT,
 PRIMARY KEY(tenant_id,rate_id),FOREIGN KEY(tenant_id,rate_id) REFERENCES offers(tenant_id,id));
CREATE VIEW IF NOT EXISTS rates AS SELECT o.*,c.eyebrow,c.long_description FROM offers o
 LEFT JOIN rate_content c ON c.tenant_id=o.tenant_id AND c.rate_id=o.id;
CREATE TABLE IF NOT EXISTS rate_card_themes (
 id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,name TEXT NOT NULL,button_color TEXT,text_color TEXT,card_fill TEXT,rate_font TEXT,accent_color_2 TEXT,legacy_option_ids_json TEXT,
 UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id) REFERENCES tenants(id));
CREATE TABLE IF NOT EXISTS rate_card_configuration (
 tenant_id TEXT NOT NULL,rate_id TEXT NOT NULL,theme_id TEXT,default_card INTEGER CHECK(default_card IN (0,1)),
 desktop_overlay_position TEXT,mobile_overlay_position TEXT,desktop_overlay_source_option_id TEXT,mobile_overlay_source_option_id TEXT,
 miles_from_center REAL CHECK(miles_from_center>=0),postal_code TEXT,PRIMARY KEY(tenant_id,rate_id),
 FOREIGN KEY(tenant_id,rate_id) REFERENCES offers(tenant_id,id),FOREIGN KEY(tenant_id,theme_id) REFERENCES rate_card_themes(tenant_id,id));
CREATE TABLE IF NOT EXISTS rate_card_global_settings (tenant_id TEXT PRIMARY KEY REFERENCES tenants(id),configurable_rate_cards INTEGER CHECK(configurable_rate_cards IN (0,1)));
CREATE TABLE IF NOT EXISTS rate_card_geographic_settings (
 tenant_id TEXT NOT NULL,rate_id TEXT NOT NULL,mode TEXT NOT NULL DEFAULT 'none' CHECK(mode IN ('none','exclude_us','exclude_north_america','international_all','international_selected')),
 PRIMARY KEY(tenant_id,rate_id),UNIQUE(tenant_id,rate_id,mode),FOREIGN KEY(tenant_id,rate_id) REFERENCES rate_card_configuration(tenant_id,rate_id));
CREATE TABLE IF NOT EXISTS rate_card_eligible_regions (
 tenant_id TEXT NOT NULL,rate_id TEXT NOT NULL,mode TEXT NOT NULL DEFAULT 'international_selected' CHECK(mode='international_selected'),
 region TEXT NOT NULL CHECK(region IN ('europe','asia','mexico','canada','united_states')),PRIMARY KEY(tenant_id,rate_id,region),
 FOREIGN KEY(tenant_id,rate_id,mode) REFERENCES rate_card_geographic_settings(tenant_id,rate_id,mode) ON DELETE CASCADE);
INSERT OR IGNORE INTO rate_card_global_settings (tenant_id) SELECT id FROM tenants;
INSERT OR IGNORE INTO rate_content (tenant_id,rate_id,eyebrow,long_description) SELECT tenant_id,id,'Save Up to 20%','
There’s something about fall in the Catskills that makes staying home feel like a mistake. Crisp mountain air, changing leaves, fireside nights, and just enough distance from the city to feel like you’ve truly gotten away.Head north and Fall for the Mountains with 20% off our best available rates when you book direct. The season doesn’t last forever — make the most of it while it’s here. ' FROM offers WHERE id='6ac3eb48c98499c5e7c9570a';
