INSERT OR IGNORE INTO rate_content (tenant_id,rate_id,eyebrow,long_description) SELECT tenant_id,id,'Breakfast Included','<p>Ease into the rhythm of the Catskills with slow mornings, fresh air, and just the right amount of indulgence. </p><p>Our Morning in the Mountains package invites you to start each day the Urban Cowboy way—unhurried, grounded, and a little bit elevated.Wake up to crisp mountain air and make your way to a thoughtfully prepared breakfast for two each morning, featuring seasonal ingredients and rustic flavors that reflect the spirit of the region. </p><p>Whether you linger over coffee or head out early to explore, it’s your time to settle in and savor.</p><p>‍</p><p>Because mornings here aren’t meant to be rushed—they’re meant to be felt.</p>' FROM offers WHERE id='6ac1d01b2807389b900a621c';
