INSERT OR IGNORE INTO rate_content (tenant_id,rate_id,eyebrow,long_description) SELECT tenant_id,id,'Hello Winter','<p>Slip away to the mountains and settle into something slower. With our Catskills Escape, the longer you linger, the more you’re rewarded—because time here is meant to be savored, not scheduled.</p><p>Enjoy a $50 lodge credit each day of your stay to use toward food, drinks, or a little something extra around the property. And with our stay more, pay less approach, you’ll receive 25% off your nightly rate—giving you every reason to extend the moment just a little longer.</p><p>‍</p><p>Unplug, unwind, and let the Catskills do the rest.</p>' FROM offers WHERE id='6ac1cfde96879b353ac42046';
